import math

def f(n):
    """Calculates the largest odd divisor of n."""
    if n <= 0:
        raise ValueError("n must be positive")
    while n % 2 == 0:
        n //= 2
    return n

def check_v(v, u_max=6):
    """
    Checks if there exists a small positive integer u (up to u_max) 
    such that all v differences are multiples of 4.
    Returns a list of solutions u.
    """
    solutions = []

    # We check u from 1 up to u_max
    for u in range(1, u_max + 1):
        all_conditions_met = True

        # Check k from v to 2v-1
        for k in range(v, 2*v):
            # Difference is f(u+k) - f(u+k-v)
            diff = f(u + k) - f(u + k - v)

            if diff % 4 != 0:
                all_conditions_met = False
                break

        if all_conditions_met:
            solutions.append(u)

    return solutions

