def check_v2(u):
    # Check conditions for v=2
    # 1. f(u+2) - f(u) mod 4 == 0
    # 2. f(u+3) - f(u+1) mod 4 == 0

    cond1 = (f(u+2) - f(u)) % 4 == 0
    cond2 = (f(u+3) - f(u+1)) % 4 == 0
    return cond1 and cond2

